/** Drops every document for one organization. Other organizations are left alone. */
export async function deleteSearchDocumentsForOrg(orgId: OrgId): Promise<void> {
  getDb().delete(searchIndex).where(orgPredicate(searchIndex.orgId, orgId)).run();
}

/**
 * A project is searchable while it is live. An issue is searchable while the
 * issue and its project are both live. A comment is searchable while the
 * comment, its issue and that issue's project are all live. Archived issues
 * stay hidden after their project is restored.
 */
function visibleDocumentPredicate(): SQL {
  return sql`(
    (${searchIndex.subjectKind} = 'project' AND EXISTS (
      SELECT 1 FROM ${projects}
      WHERE ${projects.orgId} = ${searchIndex.orgId}
        AND ${projects.id} = ${searchIndex.subjectId}
        AND ${projects.archivedAt} IS NULL
    ))
    OR (${searchIndex.subjectKind} = 'issue' AND EXISTS (
      SELECT 1 FROM ${issues}
      INNER JOIN ${projects}
        ON ${projects.id} = ${issues.projectId}
        AND ${projects.orgId} = ${issues.orgId}
      WHERE ${issues.orgId} = ${searchIndex.orgId}
        AND ${issues.id} = ${searchIndex.subjectId}
        AND ${issues.archivedAt} IS NULL
        AND ${projects.archivedAt} IS NULL
    ))
    OR (${searchIndex.subjectKind} = 'comment' AND EXISTS (
      SELECT 1 FROM ${comments}
      INNER JOIN ${issues}
        ON ${issues.id} = ${comments.issueId}
        AND ${issues.orgId} = ${comments.orgId}
      INNER JOIN ${projects}
        ON ${projects.id} = ${issues.projectId}
        AND ${projects.orgId} = ${issues.orgId}
      WHERE ${comments.orgId} = ${searchIndex.orgId}
        AND ${comments.id} = ${searchIndex.subjectId}
        AND ${comments.archivedAt} IS NULL
        AND ${issues.archivedAt} IS NULL
        AND ${projects.archivedAt} IS NULL
    ))
  )`;
}

