/**
 * Re-reads a project and every issue and comment under it. `indexIssue` and
 * `indexComment` keep archived issues hidden, including after the project
 * itself is restored.
 */
async function syncProjectSearch(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  if (project) {
    await indexProject(orgId, project);
  } else {
    await removeFromIndex(orgId, "project", projectId);
  }

  await eachPage(
    (cursor) =>
      issueRepo.listIssues({
        orgId,
        projectId,
        includeArchived: true,
        limit: INDEX_PAGE_SIZE,
        cursor,
      }),
    async (issue) => {
      await indexIssue(orgId, issue);
      await eachPage(
        (commentCursor) =>
          commentRepo.listComments({
            orgId,
            issueId: issue.id,
            includeArchived: true,
            limit: INDEX_PAGE_SIZE,
            cursor: commentCursor,
          }),
        async (comment) => {
          await indexComment(orgId, comment);
        },
      );
    },
  );
}

async function issueIsSearchable(orgId: OrgId, issue: Issue): Promise<boolean> {
  if (!isLive(issue)) return false;
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  return project !== null && isLive(project);
}

async function commentIsSearchable(
  orgId: OrgId,
  comment: Comment,
): Promise<boolean> {
  if (!isLive(comment)) return false;
  const issue = await issueRepo.findIssueById(orgId, comment.issueId);
  if (!issue) return false;
  return issueIsSearchable(orgId, issue);
}

async function removeCommentDocuments(
  orgId: OrgId,
  issueId: IssueId,
): Promise<void> {
  await eachPage(
    (cursor) =>
      commentRepo.listComments({
